        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IContainerGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AnimationSound, out var AnimationSoundInfo))
            {
                yield return AnimationSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.NativeTerminal, out var NativeTerminalInfo))
            {
                yield return NativeTerminalInfo;
            }
            if (obj.Properties is {} PropertiesItem)
            {
                foreach (var item in PropertiesItem.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.LoopingSound, out var LoopingSoundInfo))
            {
                yield return LoopingSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.CloseSound, out var CloseSoundInfo))
            {
                yield return CloseSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Template, out var TemplateInfo))
            {
                yield return TemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.OpenSound, out var OpenSoundInfo))
            {
                yield return OpenSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.CMIC, out var CMICInfo))
            {
                yield return CMICInfo;
            }
            foreach (var item in obj.DestructibleObjectFactions.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.Items is {} ItemsItem)
            {
                foreach (var item in ItemsItem.WhereCastable<IContainerEntryGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.HGLB, out var HGLBInfo))
            {
                yield return HGLBInfo;
            }
            yield break;
        }
        
